import { deflateSync } from 'node:zlib';
import { degrees, PDFDocument } from 'pdf-lib';

/** A 4x2 px JPEG with EXIF orientation 6 (displayed rotated 90° clockwise). */
export const JPEG_4X2_ORIENTATION_6 = Uint8Array.from(
  Buffer.from(
    '',
    'base64',
  ),
);

/** Builds a solid-colour RGB PNG of the given size. */
export function makePng(width: number, height: number): Uint8Array {
  const crcTable = Array.from({ length: 256 }, (_, n) => {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    return c >>> 0;
  });
  const crc32 = (data: Buffer) => {
    let c = 0xffffffff;
    for (const byte of data) c = (crcTable[(c ^ byte) & 0xff] as number) ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
  const chunk = (type: string, data: Buffer) => {
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
    const length = Buffer.alloc(4);
    length.writeUInt32BE(data.length);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body));
    return Buffer.concat([length, body, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // RGB
  const row = Buffer.concat([Buffer.from([0]), Buffer.alloc(width * 3, 0x80)]);
  const raw = Buffer.concat(Array.from({ length: height }, () => row));
  return Uint8Array.from(
    Buffer.concat([
      Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
      chunk('IHDR', ihdr),
      chunk('IDAT', deflateSync(raw)),
      chunk('IEND', Buffer.alloc(0)),
    ]),
  );
}

/**
 * Builds a PDF with one page per size; a third element sets the page's /Rotate.
 * Pages get a rectangle drawn on them unless `blank` is set.
 */
export async function makePdf(
  sizes: [number, number, number?][],
  { blank = false } = {},
): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  for (const [width, height, rotate] of sizes) {
    const page = doc.addPage([width, height]);
    if (!blank) page.drawRectangle({ x: 0, y: 0, width: width / 2, height: height / 2 });
    if (rotate) page.setRotation(degrees(rotate));
  }
  return doc.save();
}
